{"cmd": "$rates = '1k','3k','6k'
$rows = foreach ($rate in $rates) {
  $s = Get-Content "_pc_voice_rx\cycle_50\$rate\summary.json" -Raw | ConvertFrom-Json
  foreach ($b in $s.summaries) {
    $all = @($b.rows | ForEach-Object { [double]$_.total_ms })
    $steady = @($b.rows | Where-Object { $_.cycle -ge 2 } | ForEach-Object { [double]$_.total_ms })
    $enc = @($b.rows | Where-Object { $_.cycle -ge 2 } | ForEach-Object { [double]$_.encode_ms })
    $dec = @($b.rows | Where-Object { $_.cycle -ge 2 } | ForEach-Object { [double]$_.decode_ms })
    $mean = ($steady | Measure-Object -Average).Average
    $sd = if ($steady.Count -gt 1) { [math]::Sqrt((($steady | ForEach-Object { [math]::Pow($_ - $mean, 2) } | Measure-Object -Sum).Sum) / ($steady.Count - 1)) } else { 0 }
    [pscustomobject]@{
      Rate=$rate; Port=$b.port; Completed=$b.cycles_completed; Failed=$b.failures; Consistent=$b.consistent; FP=($b.unique_fingerprints -join ',')
      ColdTotal=$all[0]; SteadyMin=($steady | Measure-Object -Minimum).Minimum; SteadyMean=[math]::Round($mean,2); SteadyMax=($steady | Measure-Object -Maximum).Maximum; SteadySD=[math]::Round($sd,2); CVpct=[math]::Round(100*$sd/$mean,3)
      EncMean=[math]::Round(($enc | Measure-Object -Average).Average,2); DecMean=[math]::Round(($dec | Measure-Object -Average).Average,2); UniqueTotals=($steady | Sort-Object -Unique).Count
    }
  }
}
$rows | Format-Table -AutoSize", "workdir": "E:\jixuncodec_prj", "yield_time_ms": 10000, "max_output_tokens": 10000}

{"cmd": "$rates = '1k','3k','6k'
foreach ($rate in $rates) {
  $s = Get-Content "_pc_voice_rx\cycle_50\$rate\summary.json" -Raw | ConvertFrom-Json
  foreach ($b in $s.summaries) {
    $steady = @($b.rows | Where-Object { $_.cycle -ge 2 } | ForEach-Object { [double]$_.total_ms })
    $mean = ($steady | Measure-Object -Average).Average
    $sd = [math]::Sqrt((($steady | ForEach-Object { [math]::Pow($_ - $mean, 2) } | Measure-Object -Sum).Sum) / ($steady.Count - 1))
    $out = [ordered]@{
      rate=$rate; port=$b.port; completed=$b.cycles_completed; failed=$b.failures; consistent=$b.consistent;
      cold_total_ms=[double]$b.rows[0].total_ms; steady_min=[double](($steady | Measure-Object -Minimum).Minimum); steady_mean=[math]::Round($mean,2); steady_max=[double](($steady | Measure-Object -Maximum).Maximum); steady_stdev=[math]::Round($sd,2); cv_percent=[math]::Round(100*$sd/$mean,3); unique_total_values=@($steady | Sort-Object -Unique).Count; unique_fingerprints=$b.unique_fingerprints.Count
    }
    $out | ConvertTo-Json -Compress
  }
}", "workdir": "E:\jixuncodec_prj", "yield_time_ms": 10000, "max_output_tokens": 10000}

