#!/usr/bin/env python3
"""Compute alignment-aware SNR and PESQ metrics for captured PCM WAVs."""

import argparse
import json
import math
import sys
from pathlib import Path

import numpy as np
from scipy.signal import correlate, correlation_lags


def read_audio(path):
    import soundfile as sf

    audio, rate = sf.read(str(path), dtype="float64", always_2d=False)
    audio = np.asarray(audio, dtype=np.float64)
    if audio.ndim != 1:
        audio = audio[:, 0]
    return audio, int(rate)


def snr_db(reference, measured):
    signal_power = float(np.dot(reference, reference))
    error_power = float(np.dot(reference - measured,
                               reference - measured))
    if signal_power <= 0.0 or error_power <= 0.0:
        return None
    return 10.0 * math.log10(signal_power / error_power)


def compare_aligned(reference, measured, rate, max_lag_ms=100.0):
    reference = reference - float(reference.mean())
    measured = measured - float(measured.mean())

    correlation = correlate(measured, reference, mode="full", method="fft")
    lags = correlation_lags(len(measured), len(reference), mode="full")
    max_lag = int(round(max_lag_ms * rate / 1000.0))
    valid = np.abs(lags) <= max_lag
    valid_indices = np.flatnonzero(valid)
    if valid_indices.size == 0:
        return {}

    best_index = int(valid_indices[
        np.argmax(np.abs(correlation[valid_indices]))
    ])
    lag = int(lags[best_index])

    if lag >= 0:
        ref = reference[lag:]
        deg = measured[:len(reference) - lag]
    else:
        ref = reference[:len(reference) + lag]
        deg = measured[-lag:]

    count = min(len(ref), len(deg))
    if count < rate // 10:
        return {}
    ref = ref[:count]
    deg = deg[:count]

    deg_power = float(np.dot(deg, deg))
    scale = (float(np.dot(ref, deg)) / deg_power
             if deg_power > 0.0 else 0.0)

    correlation_coefficient = None
    if ref.std() > 0.0 and deg.std() > 0.0:
        correlation_coefficient = float(np.corrcoef(ref, deg)[0, 1])

    result = {
        "best_lag_samples": lag,
        "best_lag_ms": lag * 1000.0 / rate,
        "snr_raw_db": snr_db(ref, deg),
        "snr_gain_adjusted_db": snr_db(ref, scale * deg),
        "gain_scale": scale,
        "correlation": correlation_coefficient,
        "reference_peak": float(np.max(np.abs(ref))),
        "measured_peak": float(np.max(np.abs(deg))),
    }

    try:
        from pesq import pesq

        result["pesq_wb"] = float(pesq(
            rate,
            ref.astype(np.float32),
            deg.astype(np.float32),
            "wb",
        ))
    except Exception:
        result["pesq_wb"] = None

    return result


def analyze_capture_dir(directory):
    directory = Path(directory)
    paths = {
        "decoded_pregain": directory / "decoded_pregain.wav",
        "decoded_playback": directory / "decoded_playback.wav",
    }
    raw_path = directory / "raw_record.wav"
    if not raw_path.exists() or not all(path.exists()
                                         for path in paths.values()):
        return {}

    reference, rate = read_audio(raw_path)
    comparisons = {}
    for name, path in paths.items():
        measured, measured_rate = read_audio(path)
        if measured_rate != rate:
            raise RuntimeError(
                f"sample rate mismatch: {raw_path}={rate}, {path}={measured_rate}"
            )
        comparisons[name] = compare_aligned(reference, measured, rate)

    return {
        "rate": rate,
        "reference_samples": int(len(reference)),
        "method": (
            "Best integer-sample alignment within +/-100 ms. "
            "snr_raw_db uses no level correction; "
            "snr_gain_adjusted_db applies the least-squares scale that "
            "minimizes the error before SNR is measured."
        ),
        "comparisons": comparisons,
    }


def main():
    parser = argparse.ArgumentParser()
    parser.add_argument("directory", nargs="?", default="_pc_voice_rx")
    parser.add_argument("--write", action="store_true",
                        help="merge metrics into pcm_summary.json")
    args = parser.parse_args()
    directory = Path(args.directory)
    result = analyze_capture_dir(directory)
    if args.write and result:
        summary_path = directory / "pcm_summary.json"
        summary = {}
        if summary_path.exists():
            summary = json.loads(summary_path.read_text(encoding="utf-8"))
        summary["quality"] = result
        summary_path.write_text(
            json.dumps(summary, indent=2, ensure_ascii=True) + "\n",
            encoding="utf-8",
        )
    print(json.dumps(result, indent=2, ensure_ascii=True))
    return 0 if result else 1


if __name__ == "__main__":
    sys.exit(main())

