import wave, numpy as np
from scipy.signal import welch
for p in ['_video_demo_2min/narration_clean.wav','_video_demo_2min/narration_v2.wav']:
    with wave.open(p,'rb') as w:
        sr=w.getframerate(); a=np.frombuffer(w.readframes(w.getnframes()),dtype='<i2').astype(np.float32)/32768
    f,px=welch(a,fs=sr,nperseg=8192)
    bands={'0-4k':(0,4000),'4-8k':(4000,8000),'8-12k':(8000,12000),'12k+':(12000,sr/2)}
    total=np.trapz(px,f)
    out={name:round(float(np.trapz(px[(f>=lo)&(f<hi)],f[(f>=lo)&(f<hi)])/total*100),2) for name,(lo,hi) in bands.items()}
    print(p, 'rms_dbfs',round(float(20*np.log10(np.sqrt(np.mean(a*a))+1e-12)),2), 'peak_dbfs',round(float(20*np.log10(np.max(np.abs(a))+1e-12)),2), 'bands%',out, 'clipped',int(np.sum(np.abs(a)>0.999)))
